<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Authorship\SubordinatePersonaSectionAuthorshipService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:authorship:author-subordinate',description:'Author one exact bounded subordinate Persona section packet')]
final class AuthorshipAuthorSubordinateCommand extends Command{public function __construct(private readonly SubordinatePersonaSectionAuthorshipService$service){parent::__construct();}protected function configure():void{$this->addArgument('office',InputArgument::REQUIRED)->addArgument('acceptance-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->service->author((string)$i->getArgument('office'),(string)$i->getArgument('acceptance-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if((bool)$i->getOption('json')){$o->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return self::SUCCESS;}$o->writeln('<info>SUBORDINATE_PERSONA_SECTION_PACKET_SEALED</info> '.$r['product_id']);$o->writeln('Office: '.$r['office']);$o->writeln('Class: '.$r['authorship_class']);$o->writeln('Status: '.$r['status']);$o->writeln('Persona assembly authority: NOT GRANTED');$o->writeln('Persona approval authority: NOT GRANTED');$o->writeln('Profile approval authority: NOT GRANTED');$o->writeln('Spawning authority: NOT GRANTED');$o->writeln('Admission authority: NOT GRANTED');$o->writeln('Execution authority: NOT GRANTED');return self::SUCCESS;}}
